              return regex.test(filename.split("/").pop());
            }
            // Check if filename ends with the pattern (for paths)
            return filename.endsWith(pattern);
          });

          if (shouldExclude) {
            return;
          }

          context.report({
            node,
            messageId: "useEnvImport",
          });
        }
      },
    };
  },
};

